    ('lyrics_translation', '0'),                   -- 1 = show side-by-side English translation
    ('show_listen_together', '0'),                 -- 0 = hide button to declutter player dock
    ('theme_mode', 'dark_obsidian'),               -- 'dark_obsidian', 'oled_black', 'mica_glass'
    ('discord_rpc_enabled', '1'),
    ('download_dir', 'default_music_dir');
